                    >
                      <span className="flex items-center gap-2"><Database className="w-3 h-3" /> Force Secure Sync</span>
                      <span className={`${justSaved ? 'text-white' : 'text-emerald-600'}`}>{justSaved ? 'SAVED' : 'COMMIT'}</span>
                    </button>
                    <button 
                      onClick={() => { handleOpenKeySelection(); setIsSettingsOpen(false); }}
                      className="w-full flex items-center justify-between p-2.5 bg-cyan-600/10 hover:bg-cyan-600/20 border border-cyan-600/30 hover:border-cyan-500 transition-all text-[9px] font-black uppercase"
                    >
                      <span className="flex items-center gap-2"><Key className="w-3 h-3" /> AI Tactical Uplink</span>
                      <CheckCircle2 className="w-3 h-3 text-emerald-500" />
                    </button>
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <div className="flex items-center gap-2 text-cyan-400 border-b border-cyan-900/50 pb-2">
                  <span className="text-xs font-black bg-cyan-900 px-2 py-0.5 rounded text-white">2</span>
                  <MusicIcon className="w-4 h-4" />
                  <h3 className="text-xs font-black uppercase tracking-widest">Ambient Audio</h3>
                </div>
                <button 
                  onClick={() => setSettings(s => ({ ...s, music: !s.music }))}
                  className={`w-full p-8 flex items-center justify-between border transition-all ${settings.music ? 'border-cyan-500/50 bg-cyan-900/10' : 'border-gray-800 bg-gray-950 opacity-50'}`}
                >
                  <div className="text-left">
                    <span className="text-[12px] font-black uppercase tracking-widest block">{settings.music ? 'ENABLED' : 'DISABLED'}</span>
                    <span className="text-[8px] text-gray-500">MISSION BACKGROUND THEME</span>
                  </div>
                  {settings.music ? <Volume2 className="w-8 h-8 text-cyan-400" /> : <VolumeX className="w-8 h-8 text-gray-600" />}
                </button>
              </div>

              <div className="space-y-3">
                <div className="flex items-center gap-2 text-cyan-400 border-b border-cyan-900/50 pb-2">
                  <span className="text-xs font-black bg-cyan-900 px-2 py-0.5 rounded text-white">3</span>
                  <Volume2 className="w-4 h-4" />
                  <h3 className="text-xs font-black uppercase tracking-widest">Tactical SFX</h3>
                </div>
                <button 
                  onClick={() => setSettings(s => ({ ...s, sound: !s.sound }))}
                  className={`w-full p-8 flex items-center justify-between border transition-all ${settings.sound ? 'border-cyan-500/50 bg-cyan-900/10' : 'border-gray-800 bg-gray-950 opacity-50'}`}
                >
                  <div className="text-left">
                    <span className="text-[12px] font-black uppercase tracking-widest block">{settings.sound ? 'ENABLED' : 'DISABLED'}</span>
                    <span className="text-[8px] text-gray-500">WEAPON & ENGINE FEEDBACK</span>
                  </div>
                  {settings.sound ? <Volume2 className="w-8 h-8 text-cyan-400" /> : <VolumeX className="w-8 h-8 text-gray-600" />}
                </button>
              </div>
            </div>

            <div className="mt-10 space-y-4">
              <button 
                onClick={() => setIsSettingsOpen(false)}
                className="w-full py-5 bg-cyan-600 hover:bg-cyan-500 text-white font-black text-xl transition-all border-b-8 border-cyan-950 uppercase shadow-[0_15px_30px_rgba(6,182,212,0.2)] active:translate-y-1 active:border-b-4"
              >
                Save & Close Terminal
              </button>
              <div className="flex items-center justify-center gap-2 opacity-20">
                <ShieldAlert className="w-4 h-4 text-cyan-500" />
                <span className="text-[8px] uppercase tracking-[0.5em] font-mono">EDN-SECURE-PROTOCOL ACTIVE</span>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-hidden relative">
        {gameState === GameState.MENU && (
          <MainMenu 
            onStart={handleStartGame} 
            onContinue={handleContinueGame} 
            onOpenBase={() => openBase(GameState.MENU)} 
            onOpenLevelSelect={() => setGameState(GameState.LEVEL_SELECT)} 
            onOpenHowToPlay={() => setGameState(GameState.HOW_TO_PLAY)}
            hasSave={!!initialSaveData} 
          />
        )}

        {gameState === GameState.HOW_TO_PLAY && (
          <HowToPlay onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.LEVEL_SELECT && (
          <LevelSelect currentUnlocked={maxUnlockedLevel} onSelect={handleSelectLevel} onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.BRIEFING && (
          <Briefing briefing={briefing || {} as LevelInfo} isLoading={isBriefingLoading} onConfirm={() => setGameState(GameState.PLAYING)} />
        )}

        {isGameVisible && (
          <GameView level={level} upgrades={upgrades} isPaused={gameState === GameState.PAUSED} onWin={handleLevelComplete} onDie={handlePlayerDeath} />
        )}

        {gameState === GameState.PAUSED && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 p-4">
            <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group max-w-full font-orbitron text-center">
              <h2 className="text-4xl md:text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-6">SYSTEM SUSPENDED</h2>
              <div className="flex flex-col gap-4 items-center">
                <button onClick={() => setGameState(GameState.PLAYING)} className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase">RESUME MISSION</button>
                <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm border border-cyan-900/30 hover:border-cyan-400 mt-2">ABORT TO HQ</button>
              </div>
            </div>
          </div>
        )}

        {gameState === GameState.CHAPTER_COMPLETE && (
          <ChapterVictory chapter={level === 20 ? 1 : 2} onContinue={handleChapterContinue} />
        )}

        {gameState === GameState.LEVEL_COMPLETE && (
          <div className="fixed inset-0 bg-black/95 flex flex-col items-center justify-start md:justify-center z-50 p-6 overflow-y-auto pt-20 md:pt-6 font-orbitron">
            <h2 className="text-4xl md:text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase text-center">Sector {level} Secured</h2>
            <div className="text-xl md:text-2xl text-yellow-400 mb-8 font-bold tracking-widest text-center">REWARD EARNED: ${level > 20 ? 800 : (level === 20 ? 15000 : 300)}</div>
            <div className="flex flex-col items-center gap-6 w-full max-w-xs">
              <button onClick={() => openBase(GameState.LEVEL_COMPLETE)} className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all w-full uppercase">RETURN TO BASE</button>
              <button onClick={handleNextLevel} className={`px-12 py-4 font-black rounded-sm transition-all w-full shadow-[0_0_30px_rgba(6,182,212,0.3)] uppercase tracking-widest text-xl ${level >= MAX_CAMPAIGN_LEVELS ? 'bg-white text-black hover:bg-cyan-400' : 'bg-cyan-700 hover:bg-cyan-600 text-white'}`}>{level >= MAX_CAMPAIGN_LEVELS ? 'Finalize Victory' : `Deploy to Sector ${level + 1}`}</button>
              <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-4 border border-gray-800 hover:border-gray-400 bg-gray-950/40 w-full">Return to HQ</button>
            </div>
          </div>
        )}

        {gameState === GameState.BASE && (
          <Shop money={money} upgrades={upgrades} onBuyRobot={buyRobotTier} onBuyWeapon={buyWeaponTier} onUnlockUnit={unlockRobotUnit} onExit={handleBaseExit} isFromMenu={baseOrigin === GameState.MENU} />
        )}

        {gameState === GameState.GAMEOVER && (
          <GameOver level={level} onRetry={() => startLevel(level)} onMenu={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.VICTORY && <Victory onMenu={() => setGameState(GameState.MENU)} />}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';
import { ChevronRight } from 'lucide-react';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;
const DEATH_DURATION = 60; 

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  isDying?: boolean;
  deathTimer?: number;
  id: string;
  flightActive?: boolean;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 14, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [showCutscene, setShowCutscene] = useState(false);
  const [cutsceneStep, setCutsceneStep] = useState(0);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
    winTriggered: false,
    gameOverTriggered: false,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused || showCutscene; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades, showCutscene]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawBoss = (ctx: CanvasRenderingContext2D, en: Enemy, frame: number) => {
    ctx.save();
    ctx.translate(en.pos.x + en.width / 2, en.pos.y + en.height / 2);
    ctx.scale(en.facing || 1, 1);

    let alpha = 1;
    if (en.isDying) {
      const progress = (en.deathTimer || 0) / DEATH_DURATION;
      ctx.scale(1, 1 - progress * 0.4);
      ctx.translate(0, (en.height * 0.2) * progress);
      alpha = 1 - progress;
    } else {
      const tilt = (en.vel.x * 0.05);
      ctx.rotate(tilt);
    }
    ctx.globalAlpha = alpha;

    const isUpgraded = level > 20;
    const failThresh = en.isDying ? (DEATH_DURATION - (en.deathTimer || 0)) / DEATH_DURATION : 1.0;
    const coreActive = !en.isDying || (Math.random() < failThresh);
    const coreColor = en.isDying ? (coreActive ? '#333' : '#000') : (isUpgraded ? '#a855f7' : '#ff0000');

    if (en.type === 'titan') {
      ctx.scale(2.5, 2.5);
      drawHumanoid(ctx, en.isDying ? '#222' : '#222', frame, true, 1, 1.2, en.isDying, en.deathTimer);
      ctx.fillStyle = coreColor;
      ctx.beginPath(); ctx.arc(-5, -28, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(5, -28, 3, 0, Math.PI * 2); ctx.fill();
    } else if (en.type === 'dragon') {
      const time = frame * 0.1;
      for (let i = 0; i < 8; i++) {
        const ox = -i * 30;
        const oy = en.isDying ? 0 : Math.sin(time + i * 0.5) * 40;
        ctx.save();
        ctx.translate(ox, oy);
        drawMechanicalPart(ctx, -15, -15, 30, 30, i === 0 ? (en.isDying ? '#111' : (isUpgraded ? '#8b5cf6' : '#ff0055')) : '#220011', 8);
        if (i === 0) { 
          ctx.fillStyle = coreColor;
          ctx.fillRect(5, -8, 8, 4);
          ctx.beginPath(); ctx.moveTo(15, 0); ctx.lineTo(30, -10); ctx.lineTo(30, 10); ctx.fill();
        }
        ctx.restore();
      }
    } else if (en.type === 'omnidroid') {
      const legTime = frame * 0.2;
      ctx.fillStyle = en.isDying ? '#050505' : '#1a1a1a';
      ctx.beginPath(); ctx.arc(0, 0, 40, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = en.isDying ? '#111' : (isUpgraded ? '#8b5cf6' : '#ff0055'); ctx.lineWidth = 3; ctx.stroke();
      ctx.fillStyle = coreColor;
      ctx.beginPath(); ctx.arc(10, 0, 8, 0, Math.PI * 2); ctx.fill();
      for (let i = 0; i < 4; i++) {
        const angle = en.isDying ? (i * Math.PI / 2) : legTime + (i * Math.PI / 2);
        const lx = Math.cos(angle) * 60;
        const ly = Math.sin(angle) * 60;
        ctx.strokeStyle = '#222'; ctx.lineWidth = 6;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(lx, ly); ctx.stroke();
        ctx.fillStyle = en.isDying ? '#111' : (isUpgraded ? '#8b5cf6' : '#ff0055'); ctx.beginPath(); ctx.arc(lx, ly, 5, 0, Math.PI * 2); ctx.fill();
      }
    } else if (en.type === 'tank') {
      const isMoving = Math.abs(en.vel.x) > 0.1 && !en.isDying;
      const rock = isMoving ? Math.sin(frame * 0.2) * 2 : 0;
      const treadOffset = (frame * en.vel.x * 2) % 40;

      if (!en.isTransformed) {
         drawHumanoid(ctx, en.isDying ? '#221111' : '#552222', frame, true, 1, 1.5, en.isDying, en.deathTimer);
      } else {
        ctx.save();
        ctx.translate(0, rock);
        drawMechanicalPart(ctx, -45, 10, 90, 30, '#0a0a0a', 8);
        ctx.strokeStyle = '#111'; ctx.lineWidth = 4; ctx.setLineDash([10, 10]);
        ctx.lineDashOffset = -treadOffset; ctx.beginPath();
        ctx.moveTo(-40, 18); ctx.lineTo(40, 18); ctx.moveTo(-40, 32); ctx.lineTo(40, 32);
        ctx.stroke(); ctx.setLineDash([]);
        drawMechanicalPart(ctx, -35, -15, 75, 30, en.isDying ? '#1a0d0d' : '#331111', 4);
        ctx.save();
        const recoil = (frame % 120 < 10 && !en.isDying) ? -5 : 0;
        ctx.translate(recoil, 0);
        drawMechanicalPart(ctx, -20, -32, 45, 22, en.isDying ? '#1a0d0d' : '#552222', 2);
        drawMechanicalPart(ctx, 15, -26, 50, 10, '#050505', 1);
        ctx.restore();
        ctx.fillStyle = coreColor; ctx.fillRect(15, -24, 6, 4);
        ctx.restore();
      }
    }
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number, vel: {x:number}, flightActive?: boolean, isDying?: boolean, deathTimer?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const stats = ROBOT_STATS[unit];
    const baseColor = stats.color;
    const color = isDying ? '#1a1a1a' : baseColor;
    const tilt = vel.x * 0.02;
    if (!isDying) ctx.rotate(tilt);

    switch (unit) {
      case RobotUnit.SENTINEL: 
        drawMechanicalPart(ctx, -35, -10, 70, 24, isDying ? '#111' : '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#050505', 2);
        const siren = !isDying && Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = isDying ? '#050505' : (siren ? '#f00' : '#00f'); ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: 
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#050505'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = !isDying && Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = isDying ? '#050505' : (sirenSmall ? '#f00' : '#00f'); ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: 
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(10, -22); ctx.lineTo(30, 0); ctx.lineTo(10, 22); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -45, -8, 85, 16, '#1a1a1a', 2);
        drawMechanicalPart(ctx, 10, -6, 25, 12, isDying ? '#050505' : '#00f3ff', 8);
        if (frame % 3 !== 0 && !isDying) {
            ctx.fillStyle = '#ff7700';
            ctx.beginPath(); ctx.moveTo(-45, -5); ctx.lineTo(-65 - (Math.random() * 15), 0); ctx.lineTo(-45, 5); ctx.fill();
        }
        break;
      case RobotUnit.TITAN: 
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#0a0a0a', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#050505', 1);
        break;
      case RobotUnit.SPECTER: 
        drawMechanicalPart(ctx, -35, -15, 70, 32, isDying ? '#111' : '#fff', 4);
        ctx.fillStyle = isDying ? '#050505' : '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: 
        drawMechanicalPart(ctx, -45, -15, 90, 34, isDying ? '#1a0505' : '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#444', 1);
        break;
      case RobotUnit.NIGHTSHADE: 
        const legMov = isDying ? 0 : Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#050505', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#050505', 2);
        break;
      case RobotUnit.BLAZE: 
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#050505', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: 
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const glowAlpha = (flightActive && !isDying) ? 0.8 + Math.sin(frame * 0.4) * 0.2 : 0.1;
        ctx.fillStyle = isDying ? '#050505' : `rgba(0, 243, 255, ${glowAlpha})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: 
        drawMechanicalPart(ctx, -80, -50, 160, 90, isDying ? '#111' : '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#111', 5);
        if (frame % 5 !== 0 && !isDying) {
            ctx.fillStyle = '#00f3ff22';
            ctx.beginPath(); ctx.arc(-60, 50, 15, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.arc(60, 50, 15, 0, Math.PI * 2); ctx.fill();
        }
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1, isDying = false, deathTimer = 0) => {
    const time = isDying ? 0 : frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#050505', 6);

    const isUpgraded = isEnemy && level > 20;
    const failThresh = isDying ? (DEATH_DURATION - deathTimer) / DEATH_DURATION : 1.0;
    const coreActive = !isDying || (Math.random() < failThresh * 0.9);
    ctx.fillStyle = isDying ? (coreActive ? '#111' : '#000') : (isUpgraded ? '#a855f7' : (isEnemy ? '#ff0000' : '#00f3ff')); 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#0a0a0a', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#0a0a0a', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#050505', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#050505', 2);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, vel: {x:number}, isCombiner = false, type: string = 'grunt', flightActive?: boolean, isDying?: boolean, deathTimer?: number) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);

    if (isDying) {
      const progress = (deathTimer || 0) / DEATH_DURATION;
      ctx.scale(1, 1 - progress * 0.4); 
      ctx.translate(0, (h * 0.2) * progress);
      alpha *= (1 - progress);
    }

    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const stats = ROBOT_STATS[unit];
    const unitColor = isDying ? '#1a1a1a' : (isEnemy ? (level > 20 ? '#8b5cf6' : '#ff0055') : stats.color);

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, isDying ? '#111' : '#facc15', frame, false, drawAlpha, 3.0, isDying, deathTimer || 0);
      ctx.restore();
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha, vel, flightActive, isDying, deathTimer);
    } else {
      drawHumanoid(ctx, unitColor, frame, isEnemy, drawAlpha, 1, isDying, deathTimer || 0);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false, flightActive: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.winTriggered = false;
    e.gameOverTriggered = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 95, GROUND_Y - 48));

    const isCh2 = level > 20;
    const hpScalar = isCh2 ? 1.5 : 1;

    if (level === 20 || level === 36) {
      e.enemies = [
        { id: 101, pos: { x: 2500, y: GROUND_Y - 200 }, vel: { x: 0, y: 0 }, width: 120, height: 200, health: 5000 * hpScalar, maxHealth: 5000 * hpScalar, isDead: false, type: 'titan', lastShot: 0, facing: -1 },
        { id: 102, pos: { x: 3500, y: 200 }, vel: { x: 0, y: 0 }, width: 150, height: 100, health: 3000 * hpScalar, maxHealth: 3000 * hpScalar, isDead: false, type: 'dragon', lastShot: 0, facing: -1 },
        { id: 103, pos: { x: 4500, y: GROUND_Y - 100 }, vel: { x: 0, y: 0 }, width: 100, height: 100, health: 2500 * hpScalar, maxHealth: 2500 * hpScalar, isDead: false, type: 'omnidroid', lastShot: 0, facing: -1 },
      ];
      if (level === 20) {
        for (let i = 0; i < 2; i++) {
          e.enemies.push({ id: 200 + i, pos: { x: 2000 + i * 800, y: GROUND_Y - 40 }, vel: { x: 0, y: 0 }, width: 80, height: 40, health: 200, maxHealth: 200, isDead: false, type: 'tank', lastShot: 0, facing: -1, isTransformed: true, transformTimer: 150 });
        }
      }
    } else {
      // FORCE EXACTLY 5 EVIL ROBOTS PER LEVEL
      const enemyCount = 5;
      const isTankHeavy = level === 5 || level === 25;
      e.enemies = Array.from({ length: enemyCount }, (_, i) => ({ 
        id: i, 
        pos: { x: 1800 + i * 1100, y: GROUND_Y - (isTankHeavy ? 40 : 72) }, 
        vel: { x: 0, y: 0 }, 
        width: isTankHeavy ? 80 : 48, 
        height: isTankHeavy ? 40 : 72, 
        health: (isTankHeavy ? 200 : 100) * hpScalar, 
        maxHealth: (isTankHeavy ? 200 : 100) * hpScalar, 
        isDead: false, 
        type: isTankHeavy ? 'tank' : 'grunt', 
        lastShot: 0, 
        facing: -1,
        isTransformed: isTankHeavy ? false : undefined,
        transformTimer: isTankHeavy ? 100 + Math.random() * 200 : undefined
      }));
    }
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const isCh2 = e.level > 20;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    if (isCh2) {
      skyGrad.addColorStop(0, '#0c000c'); skyGrad.addColorStop(0.7, '#1e0a25'); skyGrad.addColorStop(1, '#4c1d95');
    } else {
      skyGrad.addColorStop(0, '#00000c'); skyGrad.addColorStop(0.7, '#2a0d08'); skyGrad.addColorStop(1, '#662200');
    }
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = isCh2 ? [
      { scroll: 0.1, color: '#0f0014', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0025', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#030005', spacing: 350, hMin: 500, hMax: 1000 },
    ] : [
      { scroll: 0.1, color: '#0c0c18', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 350, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        const flightStatus = (p.unit === RobotUnit.GLITCH && p.isTransformed && p.flightActive) ? " [FLIGHT]" : "";
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : "") + flightStatus, hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        const activeLeader = e.players.find(p => p.health > 0 && !p.isDying);
        if (activeLeader) {
          soundService.playTransform(activeLeader.unit, !activeLeader.isTransformed);
        }
        e.players.forEach(p => { if (!p.isDying) p.isTransformed = !p.isTransformed; if (!p.isTransformed) p.flightActive = false; });
      }
      if (ev.code === 'KeyF') {
        const activeLeader = e.players.find(p => p.health > 0 && !p.isDying);
        if (activeLeader && activeLeader.unit === RobotUnit.GLITCH && activeLeader.isTransformed) {
          activeLeader.flightActive = !activeLeader.flightActive;
          if (activeLeader.flightActive) soundService.playFly();
        }
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { if (!p.isDying) { p.health = Math.min(p.maxHealth, hPer); p.width = 32; p.height = 48; p.pos.x = e.players[0].pos.x - i * 90; p.pos.y = GROUND_Y - 48; } });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0 && !p.isDying);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0 && !p.isDying);

      e.players.forEach(p => {
        if (p.isDying) {
          p.deathTimer = (p.deathTimer || 0) + 1;
          p.vel.x *= 0.8;
          if (p.pos.y < GROUND_Y - p.height) p.vel.y += GRAVITY; else { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; }
          p.pos.y += p.vel.y;
          if (p.deathTimer > DEATH_DURATION) { p.health = 0; } 
        } else if (p.health <= 0 && p.health > -999) {
          p.isDying = true; p.deathTimer = 0; p.health = -999; 
          soundService.playLose();
        }
      });

      if (activeLeaderIndex === -1 && !e.gameOverTriggered) {
        const allActuallyDead = e.players.every(p => p.health <= 0 && p.isDying && (p.deathTimer || 0) >= DEATH_DURATION);
        if (allActuallyDead) { e.gameOverTriggered = true; onDie(); }
        return;
      }

      const leader = e.players[activeLeaderIndex];
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined && leader) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 60, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else if (leader) {
        e.players.forEach((p, i) => {
          if (p.health <= 0 || p.isDying) return;
          const stats = ROBOT_STATS[p.unit]; 
          const s = p.isTransformed ? stats.alt : stats.robot;
          const isActuallyFlying = (p.unit === RobotUnit.FALCON || p.unit === RobotUnit.OMEGA || (p.unit === RobotUnit.GLITCH && p.flightActive)) && p.isTransformed;

          if (i === activeLeaderIndex) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (isActuallyFlying) {
              if (moveUp) p.vel.y = -s.speed; else if (moveDown) p.vel.y = s.speed; else p.vel.y *= 0.92;
              p.grounded = false;
            } else {
              if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          } else {
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 110 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (isActuallyFlying) {
              const targetY = leader.pos.y + (i * 35);
              const hDist = targetY - p.pos.y;
              if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.7; else p.vel.y *= 0.85;
            } else {
              if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          }
          p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 20, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          const currentCombined = e.players.find(p => p.health > 0 && !p.isDying);
          if (e.isCombined && currentCombined && !currentCombined.invulnerable && b.pos.x < currentCombined.pos.x + currentCombined.width && b.pos.x + b.width > currentCombined.pos.x && b.pos.y < currentCombined.pos.y + currentCombined.height && b.pos.y + b.height > currentCombined.pos.y) {
            e.combinedHealth -= 10; currentCombined.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) { e.isCombined = false; e.players.forEach(p => p.health = 0); }
          } else if (!e.isCombined) {
            e.players.forEach(p => { 
              if (p.health > 0 && !p.isDying && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { 
                p.health -= 10; p.invulnerable = 40; e.bullets.splice(i, 1); 
              } 
            });
          }
        }
        if (leader && Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      let enemiesAliveCount = 0;
      const difficultyFactor = (e.level > 20) ? 1.25 : 1.0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        if (en.isDying) {
          en.deathTimer = (en.deathTimer || 0) + 1;
          if (en.deathTimer > DEATH_DURATION) en.isDead = true;
          return;
        }
        enemiesAliveCount++;
        const diff = (leader?.pos.x || 0) - en.pos.x;
        en.facing = Math.sign(diff) || -1;
        if (en.type === 'titan') {
          en.pos.x += Math.sign((leader?.pos.x || 0) - en.pos.x) * 1.2 * difficultyFactor;
          if (leader && Math.abs(en.pos.x - leader.pos.x) < 1600 && e.frame - en.lastShot > 100 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 100 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 10 * difficultyFactor, y: 0 }, width: 60, height: 40, owner: 'enemy', health: 1, maxHealth: 1, damage: 100, color: (e.level > 20) ? '#a855f7' : '#ff0055' });
            en.lastShot = e.frame;
          }
        } else if (en.type === 'dragon') {
          en.pos.x += Math.cos(e.frame * 0.05) * 8 * difficultyFactor;
          en.pos.y = 200 + Math.sin(e.frame * 0.05) * 100;
          if (leader && e.frame - en.lastShot > 60 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 18 * difficultyFactor, y: 4 }, width: 30, height: 30, owner: 'enemy', health: 1, maxHealth: 1, damage: 60, color: (e.level > 20) ? '#d946ef' : '#ff7700' });
            en.lastShot = e.frame;
          }
        } else if (en.type === 'omnidroid') {
          en.pos.x += Math.sign((leader?.pos.x || 0) - en.pos.x) * 4 * difficultyFactor;
          if (leader && e.frame - en.lastShot > 40 / difficultyFactor) {
            for(let j=0; j<8; j++) { const ang = (j / 8) * Math.PI * 2; e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y }, vel: { x: Math.cos(ang) * 12 * difficultyFactor, y: Math.sin(ang) * 12 * difficultyFactor }, width: 20, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#aa00ff' }); }
            en.lastShot = e.frame;
          }
        } else if (en.type === 'tank') {
          if (en.transformTimer && en.transformTimer > 0) en.transformTimer--; else { en.isTransformed = !en.isTransformed; en.transformTimer = 200 + Math.random() * 300; }
          const targetDir = Math.sign((leader?.pos.x || 0) - en.pos.x);
          if (en.isTransformed) {
            en.vel.x += targetDir * 0.02 * difficultyFactor; if (Math.abs(en.vel.x) > 1.0 * difficultyFactor) en.vel.x = Math.sign(en.vel.x) * 1.0 * difficultyFactor;
          } else en.vel.x = targetDir * 1.6 * difficultyFactor;
          en.pos.x += en.vel.x;
          if (leader && Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > (en.isTransformed ? 120 : 60) / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.isTransformed ? en.pos.y - 15 : en.pos.y + 30 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 12 * difficultyFactor, y: 0 }, width: 40, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 50, color: (e.level > 20) ? '#7e22ce' : '#550000' });
            en.lastShot = e.frame;
          }
        } else {
          en.pos.x += Math.sign((leader?.pos.x || 0) - en.pos.x) * 1.6 * difficultyFactor; en.pos.y = GROUND_Y - en.height;
          if (leader && Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 75 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 40 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 14 * difficultyFactor, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: (e.level > 20) ? '#a855f7' : '#ff0055' });
            en.lastShot = e.frame;
          }
        }

        for (let bi = e.bullets.length - 1; bi >= 0; bi--) {
          const b = e.bullets[bi];
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.health -= (b.damage || 20); e.bullets.splice(bi, 1); 
            if (en.health <= 0) { en.isDying = true; en.deathTimer = 0; soundService.playDrive(0.5); }
          }
        }
      });

      if (enemiesAliveCount === 0 && !e.winTriggered) {
        if (e.enemies.every(en => en.isDead || !en.isDying)) { e.winTriggered = true; if ([1, 5, 21].includes(e.level)) { setShowCutscene(true); setCutsceneStep(0); } else onWin(); }
      }
      if (leader) e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = (e.level > 20) ? '#0a0014' : '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = (e.level > 20) ? '#a855f711' : '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) { if (['titan', 'dragon', 'omnidroid', 'tank'].includes(en.type)) { drawBoss(ctx, en, e.frame); } else { drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, en.facing || -1, e.frame, true, false, false, 1.6, en.vel, false, 'grunt', false, en.isDying, en.deathTimer); } if (!en.isDying) { ctx.fillStyle = '#111'; ctx.fillRect(en.pos.x, en.pos.y - 15, en.width, 6); ctx.fillStyle = (e.level > 20) ? '#a855f7' : '#ff0055'; ctx.fillRect(en.pos.x, en.pos.y - 15, en.width * (en.health / en.maxHealth), 6); } } });
      const activeLeader = e.players.find(p => p.health > 0 || p.isDying);
