// Helper function to decode base64 strings to Uint8Array.
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper function to decode raw PCM audio data into an AudioBuffer.
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

class SoundService {
  private ctx: AudioContext | null = null;
  public soundEnabled: boolean = true;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return this.ctx;
  }

  /**
   * Synthesizes a driving 80s rock backing track using oscillators.
   * Includes a simple kick/snare beat and sawtooth power chords.
   */
  private playRockBackingTrack(ctx: AudioContext, duration: number) {
    const tempo = 120; // BPM
    const beatDuration = 60 / tempo;
    const startTime = ctx.currentTime;

    const playDrum = (freq: number, time: number, type: 'kick' | 'snare') => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type === 'kick' ? 'sine' : 'triangle';
      osc.frequency.setValueAtTime(freq, time);
      if (type === 'kick') {
        osc.frequency.exponentialRampToValueAtTime(30, time + 0.1);
      }
      gain.gain.setValueAtTime(0.2, time);
      gain.gain.exponentialRampToValueAtTime(0.001, time + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(time);
      osc.stop(time + 0.2);

      if (type === 'snare') {
        const noise = ctx.createBufferSource();
        const bufferSize = ctx.sampleRate * 0.1;
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
        noise.buffer = buffer;
        const filter = ctx.createBiquadFilter();
        filter.type = 'highpass';
        filter.frequency.value = 1000;
        const snareGain = ctx.createGain();
        snareGain.gain.setValueAtTime(0.12, time);
        snareGain.gain.exponentialRampToValueAtTime(0.001, time + 0.15);
        noise.connect(filter);
        filter.connect(snareGain);
        snareGain.connect(ctx.destination);
        noise.start(time);
        noise.stop(time + 0.15);
      }
    };

    const playChord = (freqs: number[], time: number, len: number) => {
      freqs.forEach(f => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(f, time);
        gain.gain.setValueAtTime(0, time);
        gain.gain.linearRampToValueAtTime(0.05, time + 0.05);
        gain.gain.linearRampToValueAtTime(0.03, time + len - 0.05);
        gain.gain.linearRampToValueAtTime(0, time + len);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(time);
        osc.stop(time + len);
      });
    };

    // Progression: C5 - G5 - A5 - F5 (classic anthem feel)
    const chords = [
      [130.81, 196.00, 261.63], // C3, G3, C4
      [98.00, 146.83, 196.00],  // G2, D3, G3
      [110.00, 164.81, 220.00], // A2, E3, A3
      [87.31, 130.81, 174.61]   // F2, C3, F3
    ];

    for (let i = 0; i < duration / beatDuration; i++) {
      const time = startTime + i * beatDuration;
      // Drums 4/4
      if (i % 2 === 0) playDrum(150, time, 'kick');
      else playDrum(250, time, 'snare');

      // Chords change every 4 beats
      if (i % 4 === 0) {
        const chordIdx = Math.floor(i / 4) % chords.length;
        playChord(chords[chordIdx], time, beatDuration * 3.8);
      }
    }
  }

  async playTheTouch() {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: 'SING ENTHUSIASTICALLY AS AN 80S ARENA ROCK STAR: You got the touch! You got the power! After all is said and done, you have never walked, you have never run, you are a winner!' }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
              voiceConfig: {
                prebuiltVoiceConfig: { voiceName: 'Puck' },
              },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(
          decode(base64Audio),
          ctx,
          24000,
          1,
        );

        // Start backing track first
        this.playRockBackingTrack(ctx, audioBuffer.duration + 2);

        // Play the TTS vocals
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;

        // Add some reverb/compression feel with a gain node
        const compressionGain = ctx.createGain();
        compressionGain.gain.value = 1.4; 

        source.connect(compressionGain);
        compressionGain.connect(ctx.destination);

        // Slight delay to allow the beat to establish
        source.start(ctx.currentTime + 0.5);
      }
    } catch (e) {
      console.error("Failed to play The Touch via TTS", e);
    }
  }

  playShoot() {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'square';
    osc.frequency.setValueAtTime(880, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(110, ctx.currentTime + 0.1);

    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.1);
  }

  playTransform(unit: RobotUnit, isEnteringAlt: boolean) {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const osc1 = ctx.createOscillator();
    const gain = ctx.createGain();

    let freqStart = 200;
    let freqEnd = 400;
    let type: OscillatorType = 'sawtooth';

    switch(unit) {
      case RobotUnit.TITAN:
      case RobotUnit.VANGUARD:
        freqStart = 100; freqEnd = 150; type = 'square'; break;
      case RobotUnit.STRIKER:
      case RobotUnit.BLAZE:
        freqStart = 400; freqEnd = 800; type = 'sine'; break;
      case RobotUnit.FALCON:
      case RobotUnit.GLITCH:
        freqStart = 300; freqEnd = 600; type = 'triangle'; break;
      case RobotUnit.OMEGA:
        freqStart = 80; freqEnd = 120; type = 'square'; break;
      case RobotUnit.SENTINEL:
      case RobotUnit.SPECTER:
      case RobotUnit.NIGHTSHADE:
        freqStart = 250; freqEnd = 450; type = 'sawtooth'; break;
    }

    if (!isEnteringAlt) {
       const temp = freqStart;
       freqStart = freqEnd;
       freqEnd = temp;
    }

    osc1.type = type;
    osc1.frequency.setValueAtTime(freqStart, ctx.currentTime);
    osc1.frequency.exponentialRampToValueAtTime(freqEnd, ctx.currentTime + 0.3);

    gain.gain.setValueAtTime(0.12, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);

    osc1.connect(gain);
    gain.connect(ctx.destination);

    osc1.start();
    osc1.stop(ctx.currentTime + 0.4);
  }

  playDrive(intensity: number = 1) {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(40 + (intensity * 20), ctx.currentTime);

    gain.gain.setValueAtTime(0.03 * intensity, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.05);
  }

  playFly() {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const bufferSize = ctx.sampleRate * 0.1;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);

    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }

    const noise = ctx.createBufferSource();
    noise.buffer = buffer;

    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(1200, ctx.currentTime);
    filter.Q.setValueAtTime(1, ctx.currentTime);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.05, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);

    noise.start();
  }

  playLose() {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'square';
    osc.frequency.setValueAtTime(220, ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(110, ctx.currentTime + 0.4);

    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.5);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.5);
  }

  playVictory() {
    if (!this.soundEnabled) return;
    const ctx = this.init();
    const playNote = (freq: number, startTime: number, duration: number, volume: number = 0.1) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, startTime);
      gain.gain.setValueAtTime(0, startTime);
      gain.gain.linearRampToValueAtTime(volume, startTime + 0.05);
      gain.gain.linearRampToValueAtTime(0, startTime + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(startTime);
      osc.stop(startTime + duration);
    };

    const notes = [261.63, 329.63, 392.00, 523.25];
    const duration = 6;
    const tempo = 0.2;

    for (let i = 0; i < duration / tempo; i++) {
      const note = notes[i % notes.length];
      playNote(note * (1 + Math.floor(i / notes.length) * 0.5), ctx.currentTime + (i * tempo), tempo, 0.08);
    }
  }
}

